package com.quotexrealvision.ai; import android.Manifest; import android.content.pm.PackageManager; import android.os.Bundle; import android.os.Handler; import android.os.Looper; import android.widget.TextView; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.camera.core.*; import androidx.camera.lifecycle.ProcessCameraProvider; import androidx.camera.view.PreviewView; import androidx.core.app.ActivityCompat; import androidx.core.content.ContextCompat; import com.google.common.util.concurrent.ListenableFuture; import java.nio.ByteBuffer; import java.util.List; import java.util.Locale; import java.util.concurrent.ExecutorService; import java.util.concurrent.Executors; public final class MainActivity extends AppCompatActivity {private static final int REQ=1001;private PreviewView preview;private TextView state,det,qual,pred,prob,why,diag;private final ExecutorService ex=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private final ChartDetector detector=new ChartDetector();private final PredictionEngine engine=new PredictionEngine();private long last=0;private boolean busy=false;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);preview=findViewById(R.id.previewView);state=findViewById(R.id.stateText);det=findViewById(R.id.detectionText);qual=findViewById(R.id.qualityText);pred=findViewById(R.id.predictionText);prob=findViewById(R.id.probabilityText);why=findViewById(R.id.whyText);diag=findViewById(R.id.diagnosticText);if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)start();else ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.CAMERA},REQ);}
private void start(){state.setText("LIVE");ListenableFuture<ProcessCameraProvider> f=ProcessCameraProvider.getInstance(this);f.addListener(()->{try{ProcessCameraProvider p=f.get();Preview pr=new Preview.Builder().build();pr.setSurfaceProvider(preview.getSurfaceProvider());ImageAnalysis a=new ImageAnalysis.Builder().setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).setOutputImageFormat(ImageAnalysis.OUTPUT_IMAGE_FORMAT_RGBA_8888).build();a.setAnalyzer(ex,this::analyze);p.unbindAll();p.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,pr,a);}catch(Exception e){state.setText("CAMERA ERROR");}},ContextCompat.getMainExecutor(this));}
private void analyze(ImageProxy img){long n=System.currentTimeMillis();if(busy||n-last<900){img.close();return;}busy=true;last=n;try{int[] px=read(img);DetectionResult d=detector.detect(px,img.getWidth(),img.getHeight());Signal s=engine.predict(d.candles,d.quality);main.post(()->render(d,s));}finally{img.close();busy=false;}}
private int[] read(ImageProxy img){ImageProxy.PlaneProxy p=img.getPlanes()[0];ByteBuffer b=p.getBuffer();int w=img.getWidth(),h=img.getHeight(),rs=p.getRowStride(),ps=p.getPixelStride();int[] o=new int[w*h];byte[] row=new byte[rs];if(ps<4)return o;for(int y=0;y<h;y++){int pos=y*rs;if(pos>=b.capacity())break;b.position(pos);int av=Math.min(rs,b.remaining());b.get(row,0,av);for(int x=0;x<w;x++){int k=x*ps;if(k+3>=av)continue;int r=row[k]&255,g=row[k+1]&255,bl=row[k+2]&255,a=row[k+3]&255;o[y*w+x]=(a<<24)|(r<<16)|(g<<8)|bl;}}return o;}
private void render(DetectionResult d,Signal s){det.setText("Detected: "+d.candles.size()+" candles");qual.setText(String.format(Locale.US,"Quality: %.0f%%",d.quality*100));if(!d.usable()){pred.setText("SCAN AGAIN");prob.setText("UP --    DOWN --");why.setText(d.message);diag.setText("Prediction blocked. This is intentional: the app will not predict from bad candle detection.");return;}pred.setText(s.label);prob.setText(String.format(Locale.US,"UP %.1f%%    DOWN %.1f%%",s.up*100,(1-s.up)*100));StringBuilder r=new StringBuilder();for(String x:s.reasons)r.append("- ").append(x).append("
");why.setText(r.toString());diag.setText(String.format(Locale.US,"Confidence %.0f%% | Agreement %.0f%% | %s",s.confidence*100,s.agreement*100,d.message));}
@Override public void onRequestPermissionsResult(int q,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(q,p,g);if(q==REQ&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)start();else state.setText("CAMERA DENIED");}@Override protected void onDestroy(){super.onDestroy();ex.shutdownNow();}}
